+// Lección candidata L-motivo-minimo-auditoria: el motivo es evidencia de auditoría; se recorta y exige >= 10 caracteres.
+export const MOTIVO_MIN_CARACTERES = 10;
+
+// Ajuste por recuento (ADR-001): si lo contado difiere del stock calculado, agrega un movimiento por la
+// diferencia (ingreso si sobra, egreso si falta); si no difiere, devuelve la misma lista sin cambios.
+export function ajustarInventario(movimientos, { articulo, almacen, cantidadContada, motivo } = {}) {
+  if (!articulo || !almacen) throw new Error("El ajuste necesita artículo y almacén");
+  if (!Number.isInteger(cantidadContada) || cantidadContada < 0)
+    throw new RangeError("La cantidad contada debe ser un entero mayor o igual a cero");
+  const motivoRecortado = typeof motivo === "string" ? motivo.trim() : "";
+  if ([...motivoRecortado].length < MOTIVO_MIN_CARACTERES)
+    throw new RangeError(`El motivo debe tener al menos ${MOTIVO_MIN_CARACTERES} caracteres`);
+  const diferencia = cantidadContada - stock(movimientos, articulo, almacen);
+  if (diferencia === 0) return movimientos;
+  return registrarMovimiento(movimientos, {
+    tipo: diferencia > 0 ? "ingreso" : "egreso",
+    articulo,
+    almacen,
+    cantidad: Math.abs(diferencia),
+    motivo: motivoRecortado,
+  });
+}
